    private double balance;

    void deposit(double amount) {
        balance = balance + amount;
    }

    void withdraw(double amount) {
        if(amount <= balance) {
            balance = balance - amount;
        } else {
            System.out.println("Insufficient funds");
        }
    }

    void printBalance() {
        System.out.printf("Balance: %.2f%n", balance);
    }

    double getBalance() {
        return balance;
    }
}

